      hu: ["Tengerszint feletti magasság: 1700-2200 méter", "Kávétípus: Főként mosott Arabica", "Ízjegyek: Jázmin, citrom és virágos aromák", "Szüreti időszak: Októbertől januárig", "Régió: Gedeo zóna, Déli nemzetek és népek régiója", "Feldolgozás: Híres a precíz nedves eljárásról"],
      ro: ["Altitudine: 1.700 până la 2.200 de metri", "Tip de cafea: Arabica procesată predominant prin spălare", "Profil gustativ: Note florale, iasomie și citrice", "Perioada de recoltare: Octombrie – Ianuarie", "Locație: Zona Gedeo, Regiunea Națiunilor din Sud", "Procesare: Renumită pentru metoda de procesare umedă (washed)"],
      en: ["Elevation: 1,700 to 2,200 meters above sea level", "Coffee type: Primarily washed Arabica", "Flavor profile: Floral notes, jasmine, and citrus", "Harvest season: October to January", "Region: Gedeo Zone, Southern Nations Region", "Processing: Famous for pioneering the wet processing method in Ethiopia"],
      es: ["Altitud: de 1.700 a 2.200 metros sobre el nivel del mar.", "Variedad de café: Predominantemente arábica lavado.", "Perfil de sabor: Notas florales, jazmín y cítricos.", "Época de cosecha: De octubre a enero.", "Ubicación: Zona de Gedeo, Región de las Naciones del Sur.", "Procesamiento: Conocido por introducir el procesamiento húmedo en Etiopía."],
      pt: ["Altitude: 1.700 a 2.200 metros acima do nível do mar.", "Variedade de café: Predominantemente Arábica lavado.", "Perfil de sabor: Notas florais, jasmim e citrinos.", "Época de colheita: Outubro a janeiro.", "Localização: Zona de Gedeo, Região das Nações do Sul.", "Processamento: Conhecido pela introdução do processamento por via húmida na Etiópia."],
      fr: ["Altitude : 1 700 à 2 200 mètres au-dessus du niveau de la mer.", "Variété de café : Principalement de l'Arabica lavé.", "Profil gustatif : Notes florales, jasmin et agrumes.", "Période de récolte : D'octobre à janvier.", "Localisation : Zone de Gedeo, Région des nations du sud.", "Traitement : Connu pour avoir introduit le traitement par voie humide en Éthiopie."],
